var FindDuplicateRecords = Class.create();
FindDuplicateRecords.prototype = {
    initialize: function() {},

    findDuplicates: function(tableName, fieldName) {
         var agg = new GlideAggregate('cmn_location');
    agg.addAggregate('COUNT', 'name'); // Static field name 'name'
    agg.groupBy('name');
    agg.addHaving('COUNT', 'name', '>', 1);
    agg.query();

    var duplicateCount = 0; // Counter for duplicate records

    while (agg.next()) {
        var duplicateValue = agg.getValue('name');
        var count = agg.getAggregate('COUNT', 'name');

        gs.info('Duplicate Record Found: ' + duplicateValue + ' - Count: ' + count);
        duplicateCount++;
    }

    gs.info('Total Duplicate Records Found: ' + duplicateCount);
        return result; // Returns an array of duplicate values and their count
    },

    type: 'FindDuplicateRecords'
};
